// 密码强度校验：长度 / 字符类别 / 常见弱口令 / 不含用户名 —— 正反用例
const COMMON = new Set(['password', 'password123', '123456789012', 'qwertyuiop12', 'admin admin'.replace(' ', '')]);

function checkStrength(password, username) {
  const rules = {
    min_length_12: password.length >= 12,
    has_lower: /[a-z]/.test(password),
    has_upper: /[A-Z]/.test(password),
    has_digit: /[0-9]/.test(password),
    has_symbol: /[^A-Za-z0-9]/.test(password),
    not_common: !COMMON.has(password.toLowerCase()),
    no_username: username ? password.toLowerCase().indexOf(username.toLowerCase()) === -1 : true,
  };
  const passed = Object.keys(rules).filter(k => rules[k]).length;
  return { ok: Object.keys(rules).every(k => rules[k]), rules, score: passed };
}

const cases = [
  ['strong_passphrase', 'Correct-Horse-9-Battery', 'alice', true],
  ['too_short', 'Ab1!xY', 'alice', false],
  ['no_symbol', 'CorrectHorse9Battery', 'alice', false],
  ['no_upper', 'correct-horse-9-battery', 'alice', false],
  ['common_password', 'Password123'.padEnd(12, 'x'), 'alice', false],
  ['contains_username', 'alice-Long-Pass-9!', 'alice', false],
];
let pass = 0;
for (const [name, pw, user, expect] of cases) {
  const r = checkStrength(pw, user);
  if (r.ok === expect) pass += 1;
  console.log(name + ' ok=' + r.ok + ' expect=' + expect + ' score=' + r.score + '/7 match=' + (r.ok === expect));
}
console.log('pass_count=' + pass + '/' + cases.length);
console.log('all_match=' + (pass === cases.length));
console.log('rules_are_independent_booleans=true');
